import type { ReactNode } from "react";

/** A band of light that sweeps across a card or an image when the pointer or keyboard focus reaches it. */
export interface GlareHoverSpecProps {
  /**
   * The content to sweep across.
   */
  children: ReactNode;
  /**
   * Tilt of the band in degrees.
   * @default -20
   */
  angle?: number;
  /**
   * Seconds for one sweep.
   * @default 0.7
   */
  duration?: number;
  /**
   * Colour of the glare, any CSS colour. Defaults to white at low strength.
   */
  color?: string;
  /**
   * Stops the effect and shows it still.
   * @default false
   */
  isPaused?: boolean;
}

export const glareHoverDefaults = {
  angle: -20,
  duration: 0.7,
  isPaused: false,
} as const;

export const glareHoverMeta = {
  "name": "GlareHover",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;
